<script setup lang="ts">
/**
 * A screenshot of the app generated by `npm run docs:screenshots`, in the page's language.
 * Both the light and the dark variant are rendered and CSS shows the one matching the site
 * theme (no flash, no hydration mismatch). Click or press Enter to see it full size.
 */
import { computed, ref } from 'vue'
import { useData, withBase } from 'vitepress'
import manifest from '../../screenshots.json'

const props = defineProps<{
  /** Scene name from `docs/.screenshots/scenes.spec.ts`. */
  name: string
  /** What the picture shows, for screen readers and when images don't load. */
  alt: string
  caption?: string
}>()

const { lang, isDark } = useData()
const sizes = (manifest as Record<string, Record<string, [number, number]>>)[props.name]
if (!sizes) throw new Error(`Unknown screenshot "${props.name}". Run npm run docs:screenshots.`)

const language = computed(() => (lang.value.startsWith('pl') ? 'pl' : 'en'))
const variants = computed(() =>
  (['light', 'dark'] as const).map((theme) => {
    const [width, height] = sizes[`${language.value}-${theme}`] ?? sizes[`en-${theme}`] ?? [0, 0]
    return {
      theme,
      width,
      height,
      src: withBase(`/screenshots/${language.value}/${theme}/${props.name}.webp`)
    }
  })
)
const current = computed(() => variants.value[isDark.value ? 1 : 0]!)
const enlargeLabel = computed(() =>
  language.value === 'pl' ? `Powiększ: ${props.alt}` : `Enlarge: ${props.alt}`
)
const closeLabel = computed(() => (language.value === 'pl' ? 'Zamknij' : 'Close'))

const zoom = ref<HTMLDialogElement>()
const open = (): void => zoom.value?.showModal()
const close = (): void => zoom.value?.close()
</script>

<template>
  <figure class="fi-shot">
    <button type="button" class="fi-shot__open" :aria-label="enlargeLabel" @click="open">
      <img
        v-for="v in variants"
        :key="v.theme"
        :class="`fi-shot__img fi-shot__img--${v.theme}`"
        :src="v.src"
        :width="v.width"
        :height="v.height"
        :alt="alt"
        loading="lazy"
        decoding="async"
      />
    </button>
    <figcaption v-if="caption">{{ caption }}</figcaption>
    <dialog ref="zoom" class="fi-shot__zoom" :aria-label="alt" @click="close">
      <img :src="current.src" :width="current.width" :height="current.height" :alt="alt" />
      <button type="button" class="fi-shot__close" @click.stop="close">
        {{ closeLabel }} <kbd>Esc</kbd>
      </button>
    </dialog>
  </figure>
</template>

<style scoped>
.fi-shot {
  margin: 20px 0;
}

.fi-shot__open {
  display: block;
  max-width: 100%;
  padding: 0;
  border: 1px solid var(--vp-c-divider);
  border-radius: 10px;
  overflow: hidden;
  background: var(--vp-c-bg-soft);
  box-shadow: var(--fi-shadow-sm);
  cursor: zoom-in;
  transition: box-shadow 0.2s;
}

.fi-shot__open:hover {
  box-shadow: var(--fi-shadow);
}

.fi-shot__open:focus-visible {
  outline: 3px solid var(--vp-c-brand-1);
  outline-offset: 3px;
}

.fi-shot__img {
  display: block;
  max-width: 100%;
  height: auto;
}

.dark .fi-shot__img--light,
html:not(.dark) .fi-shot__img--dark {
  display: none;
}

figcaption {
  margin-top: 8px;
  color: var(--vp-c-text-2);
  font-size: 14px;
  line-height: 1.5;
}

.fi-shot__zoom {
  max-width: 96vw;
  max-height: 96vh;
  padding: 0;
  border: 0;
  border-radius: 12px;
  background: var(--vp-c-bg);
  box-shadow: var(--fi-shadow);
  overflow: auto;
  cursor: zoom-out;
}

.fi-shot__zoom::backdrop {
  background: rgb(0 0 0 / 70%);
}

.fi-shot__zoom img {
  display: block;
  max-width: none;
}

.fi-shot__close {
  position: fixed;
  top: 16px;
  right: 16px;
  padding: 6px 12px;
  border-radius: 8px;
  background: var(--vp-c-bg);
  color: var(--vp-c-text-1);
  font-size: 14px;
  font-weight: 600;
  box-shadow: var(--fi-shadow);
}
</style>
